import sqlite3,os,pandas as pd,plotly.graph_objects as go,streamlit as st
DB='data/lifestyle.db';st.set_page_config(page_title='Location Lifestyle AI v2.1',page_icon='🏡',layout='wide');st.title('🏡 Location Lifestyle AI v2.1');st.caption('Large catalogue and repository-owned evidence database')
if not os.path.exists(DB):st.error('Database missing. The included GitHub Action runs automatically after upload. Check the Actions tab, then reboot Streamlit.');st.stop()
c=sqlite3.connect(DB);loc=pd.read_sql('select * from locations order by region,name',c);ready=loc[loc.status=='refreshed'];pending=loc[loc.status!='refreshed'];a,b=st.columns(2);a.metric('Locations in catalogue',len(loc));b.metric('Locations refreshed',len(ready));
if ready.empty:st.warning('Catalogue is installed, but evidence refresh has not completed. Check the repository Actions tab.');st.dataframe(loc[['name','region','status']],hide_index=True,use_container_width=True);st.stop()
choices=ready.name.tolist();x1,x2=st.columns(2);current=x1.selectbox('Current location',choices,index=choices.index('Marlow') if 'Marlow' in choices else 0);dest=x2.selectbox('Destination',choices,index=choices.index('Henley-on-Thames') if 'Henley-on-Thames' in choices else min(1,len(choices)-1))
def data(n):
 lid=int(ready[ready.name==n].iloc[0].id);return pd.read_sql('select category,name,detail,source from evidence where location_id=?',c,params=(lid,)),pd.read_sql('select key,value,unit,source from metrics where location_id=?',c,params=(lid,)),pd.read_sql('select source,status,detail,refreshed_at from sources where location_id=?',c,params=(lid,))
ea,ma,sa=data(current);eb,mb,sb=data(dest);cats=sorted(set(ea.category)|set(eb.category));d=pd.DataFrame({'Category':cats,current:[sum(ea.category==k) for k in cats],dest:[sum(eb.category==k) for k in cats]});fig=go.Figure();fig.add_bar(name=current,x=d.Category,y=d[current]);fig.add_bar(name=dest,x=d.Category,y=d[dest]);fig.update_layout(barmode='group',title='Stored evidence records');st.plotly_chart(fig,use_container_width=True);st.dataframe(d,hide_index=True,use_container_width=True)
for k in cats:
 with st.expander(k):st.dataframe(eb[eb.category==k][['name','detail','source']].head(50),hide_index=True,use_container_width=True)
with st.expander('Provenance',expanded=True):st.dataframe(pd.concat([sa.assign(location=current),sb.assign(location=dest)])[['location','source','status','detail','refreshed_at']],hide_index=True,use_container_width=True)
